const crypto = require('crypto');

// Verifies the HMAC signature Convex puts on every request event (see README, Signing).
const PATH = '/webhook/lendloop-request-events';
const TOLERANCE_SECONDS = 300;
const secret = $env.LENDLOOP_WEBHOOK_SECRET;

const item = $input.first();
const headers = item.json.headers || {};
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '');
const raw = item.binary && item.binary.data
  ? (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8')
  : '';

function rejectReason() {
  if (!secret) return 'not_configured';
  if (!timestamp || !signature) return 'missing_headers';
  if (!/^\d{1,12}$/.test(timestamp) || !/^v1=[0-9a-f]{64}$/.test(signature)) return 'malformed';
  if (Math.abs(Date.now() / 1000 - Number(timestamp)) > TOLERANCE_SECONDS) return 'stale';
  const expected = crypto.createHmac('sha256', secret).update(timestamp + '.POST.' + PATH + '.' + raw).digest();
  return crypto.timingSafeEqual(expected, Buffer.from(signature.slice(3), 'hex')) ? null : 'bad_signature';
}

const reason = rejectReason();
if (reason) {
  console.warn('[lendloop] rejected request event: ' + reason);
  return [{ json: { valid: false, reason } }];
}
return [{ json: { valid: true, event: JSON.parse(raw) } }];

// Mock delivery: logs the message instead of sending an email. Uses only the fields in the event.
const e = $input.first().json.event;
const range = e.request.startDate === e.request.endDate
  ? e.request.startDate
  : e.request.startDate + ' to ' + e.request.endDate;
const name = e.recipient.displayName;
const messages = {
  'request.created': name + ', a neighbor asked to borrow your ' + e.tool.name + ' (' + range + '). Open LendLoop to approve or decline.',
  'request.approved': name + ', your request for the ' + e.tool.name + ' (' + range + ') was approved.',
  'request.declined': name + ', your request for the ' + e.tool.name + ' (' + range + ') was declined.',
  'request.cancelled': name + ', the request for your ' + e.tool.name + ' (' + range + ') was cancelled.',
  'request.returned': name + ', the ' + e.tool.name + ' was marked returned. Thanks for borrowing!',
};
const text = messages[e.type];
if (!text) throw new Error('Unknown event type: ' + e.type);

console.log('[lendloop] notify to=' + e.recipient.clerkUserId + ' event=' + e.type + ' id=' + e.eventId + ': ' + text);
return [{ json: { eventId: e.eventId, channel: 'log', to: e.recipient.clerkUserId, text } }];

const crypto = require('crypto');

// Signs a call to Convex: HMAC-SHA256 over "timestamp.METHOD.path.body" (see README, Signing).
function signForConvex(path, payload) {
  const secret = $env.LENDLOOP_CONVEX_API_SECRET;
  const baseUrl = $env.LENDLOOP_CONVEX_SITE_URL;
  if (!secret || !baseUrl) throw new Error('LENDLOOP_CONVEX_API_SECRET or LENDLOOP_CONVEX_SITE_URL is not set');
  const body = JSON.stringify(payload);
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const mac = crypto.createHmac('sha256', secret).update(timestamp + '.POST.' + path + '.' + body).digest('hex');
  return { url: baseUrl + path, body, timestamp, signature: 'v1=' + mac };
}

return [{ json: signForConvex('/automation/notifications', { eventId: $input.first().json.eventId }) }];
